insert into pillars (title, summary, image_url, sort) values
  ('Education', 'Teaching that works for students: fair and clear rules on AI and exams, study materials you can afford, and the support you need to learn well.', 'img/pillars/education.jpg', 1),
  ('Internationalism', 'Keeping UM a university for students from everywhere: teaching in English, good translation and language help, and a place for Dutch and international students side by side.', 'img/pillars/internationalism.jpg', 2),
  ('Wellbeing', 'A campus where everyone feels safe and supported, with attention for mental health, sexual safety, and students with visible or invisible disabilities.', 'img/pillars/wellbeing.jpg', 3),
  ('Housing', 'A safe, affordable room for every student: quick fixes for the September rush, decent living conditions, and long-term plans together with the municipality.', 'img/pillars/housing.jpg', 4),
  ('Sustainability', 'A university that takes the climate seriously: reaching carbon neutrality, greener day-to-day operations, and honest choices about who UM works with and invests in.', 'img/pillars/sustainability.jpg', 5);
